export declare const VIDEO_DELIVERY_CONTRACT = "# \u89C6\u9891\u524D\u671F\u4EA4\u4ED8\u6A21\u677F\u5951\u7EA6\n\n\u8FD9\u4EFD\u5951\u7EA6\u5B9A\u4E49\u89C6\u9891\u524D\u671F\u5236\u54C1\u7684**\u56FA\u5B9A\u7EC4\u7EC7\u7ED3\u6784\u3001\u5206\u6790\u89D2\u5EA6\u3001\u6700\u5C0F\u7C92\u5EA6\u548C\u9A8C\u6536\u65B9\u5F0F**\u3002\u5B83\u9AD8\u4E8E\u4EFB\u4F55\u7B80\u7248\u7ED3\u6784\u5361\u3002\u66FF\u6362\u9879\u76EE\u4E8B\u5B9E\u3001\u4EA7\u54C1\u540D\u3001\u4EBA\u7269\u3001\u573A\u666F\u3001\u65F6\u957F\u548C\u6848\u4F8B\uFF1B\u4E0D\u5F97\u5220\u51CF\u5176\u4E2D\u8981\u6C42\u7684\u7AE0\u8282\u3001\u5F15\u7528\u5173\u7CFB\u3001\u9A8C\u6536\u6216\u4E8B\u5B9E\u8FB9\u754C\u3002\n\n## \u4F7F\u7528\u987A\u5E8F\u4E0E\u8FB9\u754C\n\n`\u539F\u59CB\u811A\u672C/\u4EA7\u54C1\u8D44\u6599 \u2192 \u5927\u7EB2\u811A\u672C \u2192 \u5206\u955C\u7A3F \u2192 \u53E3\u64AD\u53F0\u8BCD\u7A3F \u2192 \u53E3\u64AD\u5F55\u5236\u6267\u884C\u7A3F \u2192 \u524D\u671F\u7D20\u6750\u6267\u884C\u5305 \u2192 \u5236\u4F5C\u6267\u884C`\n\n\u539F\u59CB\u811A\u672C\u662F\u8F93\u5165\u3002\u524D\u671F\u7D20\u6750\u6267\u884C\u5305\u4E0D\u5206\u914D\u4EBA\u5458\u3001\u4E0D\u7ED1\u5B9A\u526A\u8F91\u5DE5\u5177\uFF1B\u5B83\u53EA\u9501\u5B9A\u4E3A\u4E86\u5B8C\u6210\u6210\u7247\u800C\u5FC5\u987B\u5B58\u5728\u7684\u524D\u671F\u6761\u4EF6\u3002\u6BCF\u4EFD\u6587\u4EF6\u5FC5\u987B\u6807\u660E\u8F93\u5165\u7248\u672C\u548C\u751F\u6210\u7248\u672C\u3002\n\n## \u6240\u6709\u5236\u54C1\u5171\u7528\u8F93\u5165\u5757\n\n\u6BCF\u4EFD\u4EA4\u4ED8\u5F00\u59CB\u524D\uFF0C\u5148\u660E\u786E\u4E0B\u5217\u4FE1\u606F\uFF1B\u672A\u77E5\u9879\u5199`\u5F85\u786E\u8BA4`\uFF0C\u7EDD\u4E0D\u7F16\u9020\uFF1A\n\n- **\u9879\u76EE\u57FA\u7840**\uFF1A\u6807\u9898\u3001\u7C7B\u578B\u3001\u53D1\u5E03\u5E73\u53F0/\u753B\u5E45\u3001\u76EE\u6807\u65F6\u957F\u3001\u76EE\u6807\u89C2\u4F17\u3001\u770B\u5B8C\u540E\u7684\u8BB0\u5FC6\u6216\u884C\u52A8\u3002\n- **\u5185\u5BB9\u4E0E\u6848\u4F8B**\uFF1A\u4EA7\u54C1/\u4E3B\u9898\u3001\u6838\u5FC3\u80FD\u529B\u3001\u552F\u4E00\u4F20\u64AD\u6BCD\u9898\u3001\u5177\u4F53\u4EFB\u52A1\u573A\u666F\u3001\u53EF\u89C1\u7ED3\u679C\u3001\u5FC5\u987B\u771F\u5B9E\u8BC1\u660E\u7684\u4E3B\u5F20\u3002\n- **\u53EF\u7528\u8D44\u6E90**\uFF1A\u5DF2\u6709\u811A\u672C/\u7D20\u6750\u3001\u53EF\u5F55\u5C4F\u754C\u9762\u3001\u53EF\u62CD\u573A\u666F\u3001B-roll \u6765\u6E90\u3001\u4EBA\u5458\u4E0E\u8BBE\u5907\u9650\u5236\u3002\n- **\u8FB9\u754C**\uFF1A\u4E0D\u53EF\u5C55\u793A/\u987B\u6253\u7801\u9879\u3001\u4E0D\u53EF\u5938\u5927\u80FD\u529B\u3001\u5FC5\u987B\u51FA\u73B0\u672F\u8BED\u4E0E CTA\u3001\u6240\u9700\u6587\u4EF6\u683C\u5F0F\u3002\n\n\u540C\u4E00\u9879\u4E8B\u5B9E\u5FC5\u987B\u5728\u6240\u6709\u5236\u54C1\u4E2D\u4F7F\u7528\u76F8\u540C ID \u4E0E\u8868\u8FF0\u3002\u53D1\u73B0\u8BC1\u636E\u4E0D\u6210\u7ACB\u65F6\uFF0C\u56DE\u6D41\u4E0A\u6E38\u5220\u6539\u4E3B\u5F20\uFF0C\u800C\u4E0D\u662F\u6539\u5199\u4E3A\u66F4\u6A21\u7CCA\u7684\u8BDD\u3002\n\n---\n\n## A. \u5927\u7EB2\u811A\u672C\uFF08Node 3\uFF09\n\n### \u56FA\u5B9A\u7ED3\u6784\n\n1. \u9876\u90E8\u6458\u8981\uFF1A\u76EE\u6807\u65F6\u957F\u3001\u552F\u4E00\u4F20\u64AD\u6BCD\u9898\u3001\u5F00\u573A\u7ED3\u679C/\u65AD\u70B9\u3001\u6838\u5FC3\u8BC1\u660E\u94FE\u3001\u7ED3\u675F\u52A8\u4F5C\u3002\n2. \u6BB5\u843D\u65F6\u95F4\u7EBF\u603B\u89C8\uFF1A`\u6BB5\u843D ID\uFF5C\u8D77\u6B62\u65F6\u95F4\uFF5C\u65F6\u957F\uFF5C\u53D9\u4E8B\u4EFB\u52A1\uFF5C\u89C2\u4F17\u7406\u89E3\u53D8\u5316`\u3002\n3. \u9010\u6BB5\u5927\u7EB2\uFF1A`\u6BB5\u843D ID\uFF5C\u53E3\u64AD\u65B9\u5411\uFF5C\u51FA\u955C/\u5448\u73B0\u89D2\u8272\uFF5C\u53EF\u89C1\u627F\u8BFA\uFF5C\u8BC1\u660E\u76EE\u6807\uFF5C\u9700\u8981\u7684\u771F\u5B9E\u72B6\u6001\uFF5C\u8F6C\u573A\uFF5C\u4E0D\u652F\u6301\u4E3B\u5F20`\u3002\n4. \u4E3B\u5F20\u4E0E\u8BC1\u636E\u8FB9\u754C\uFF1A\u9010\u6761\u5217\u51FA\u53EF\u8BC1\u660E\u3001\u5F85\u8865\u8BC1\u4E0E\u5FC5\u987B\u5220\u9664\u7684\u4E3B\u5F20\u3002\n5. \u9501\u5B9A\u68C0\u67E5\uFF1A\u65F6\u957F\u3001\u6BB5\u843D\u63A8\u8FDB\u3001\u5F00\u573A\u3001\u8BC1\u660E\u94FE\u3001CTA \u4E0E\u5F85\u786E\u8BA4\u9879\u3002\n\n### \u7C92\u5EA6\u4E0E\u5224\u65AD\n\n\u6BCF\u6BB5\u53EA\u80FD\u627F\u62C5\u4E00\u4E2A\u4E3B\u5BFC\u53D9\u4E8B\u4EFB\u52A1\uFF0C\u4F46\u53EF\u4EE5\u4F7F\u7528\u53E3\u64AD\u3001\u6F14\u793A\u3001\u771F\u4EBA\u3001\u8BBF\u8C08\u3001B-roll\u3001\u56FE\u5F62\u6216\u9759\u9ED8\u5B9E\u73B0\u3002\u5B83\u5FC5\u987B\u8BA9\u4E0B\u6E38\u65E0\u9700\u731C\u6D4B\uFF1A\u8FD9\u4E00\u6BB5\u8BA9\u89C2\u4F17**\u770B\u5230\u4EC0\u4E48\u3001\u76F8\u4FE1\u4EC0\u4E48\u3001\u51ED\u4EC0\u4E48\u76F8\u4FE1\u3001\u5982\u4F55\u8FDB\u5165\u4E0B\u4E00\u6BB5**\u3002\u4E0D\u5199\u9010\u5B57\u53F0\u8BCD\uFF0C\u4E0D\u5199\u9010\u955C\u5934\u8C03\u5EA6\u3002\n\n---\n\n## B. \u5206\u955C\u7A3F\uFF08Node 4 \u7684\u5206\u955C\u4E3B\u7A3F\uFF09\n\n### \u56FA\u5B9A\u7ED3\u6784\n\n1. \u9876\u90E8\u6458\u8981\uFF1A\u76EE\u6807\u65F6\u957F\u3001\u573A\u666F/\u6848\u4F8B\u3001\u53EF\u89C1\u7ED3\u679C\u3001\u4F20\u64AD\u6BCD\u9898\u3001\u771F\u4EBA\u673A\u4F4D\u7B56\u7565\u3001\u771F\u5B9E\u8BC1\u660E\u8FB9\u754C\u3002\n2. \u5168\u7247\u65F6\u95F4\u7EBF\uFF1A`\u6BB5\u843D\uFF5C\u8D77\u6B62\u65F6\u95F4\uFF5C\u65F6\u957F\uFF5C\u53D9\u4E8B\u4EFB\u52A1`\u3002\n3. \u6309\u6700\u7EC8\u89C2\u770B\u987A\u5E8F\u7684\u9010\u955C\u8868\uFF1A\n\n`\u955C\u53F7\uFF5C\u65F6\u95F4\uFF5C\u753B\u9762\u4E0E\u673A\u4F4D\uFF5C\u753B\u9762\u52A8\u4F5C\u4E0E\u5C4F\u5E55\u6587\u5B57\uFF5C\u5BF9\u5E94\u53F0\u8BCD ID\uFF5C\u6E90\u7D20\u6750 ID/\u7247\u6BB5 ID\uFF5C\u540E\u671F\u8BF4\u660E\uFF5C\u8BC1\u636E\u7C7B\u578B\uFF5C\u8BE5\u955C\u5934\u9A8C\u6536`\n\n4. \u6BCF\u4E2A\u5173\u952E\u6BB5\u843D\u7684\u9A8C\u6536\uFF1A\u89C2\u4F17\u5FC5\u987B\u770B\u5230\u4EC0\u4E48\u3001\u5B83\u8BC1\u660E\u54EA\u6761\u4E3B\u5F20\u3001\u7F3A\u5931\u65F6\u662F\u8865\u5F55\u3001\u56DE\u6D41\u6539\u5199\u8FD8\u662F\u53EF\u7528\u540E\u671F\u8868\u8FBE\u3002\n5. \u56FA\u5B9A\u8F93\u5165\u6587\u672C\u3001\u5173\u952E\u672F\u8BED\u3001\u6D4B\u8BD5\u6761\u4EF6\u3001\u6700\u7EC8\u7ED3\u679C\u6838\u9A8C\u9879\u3002\n\n### \u786C\u7EA6\u675F\n\n- \u5206\u955C\u6309\u89C2\u770B\u987A\u5E8F\u5199\uFF0C\u91C7\u96C6\u987A\u5E8F\u653E\u5728\u524D\u671F\u7D20\u6750\u6267\u884C\u5305\u3002\n- \u5F00\u573A\u4F18\u5148\u653E\u7ED3\u679C\u6216\u5177\u4F53\u65AD\u70B9\uFF0C\u518D\u89E3\u91CA\u673A\u5236\u3002\n- \u6BCF\u6761\u6838\u5FC3\u4E3B\u5F20\u6709\u771F\u5B9E\u8BC1\u660E\u955C\u5934\uFF1B\u56FE\u5F62/B-roll\u53EA\u80FD\u89E3\u91CA\u3001\u8282\u594F\u6216\u8F6C\u573A\uFF0C\u4E0D\u80FD\u4EE3\u66FF\u771F\u5B9E UI\u3001\u64CD\u4F5C\u6216\u7ED3\u679C\u3002\n- \u6BCF\u6B21\u6BCD\u7D20\u6750\u590D\u7528\u5FC5\u987B\u663E\u5F0F\u6307\u5411\u6E90\u7D20\u6750\u4E0E\u7247\u6BB5\uFF1B\u65E0\u590D\u7528\u4EF7\u503C\u7684\u4E00\u6B21\u6027\u955C\u5934\u9700\u8981\u5FC5\u8981\u6027\u7406\u7531\u3002\n- \u771F\u4EBA\u6CA1\u6709\u53D9\u4E8B\u7406\u7531\u65F6\u4FDD\u6301\u540C\u4E00\u56FA\u5B9A\u666F\u522B\uFF1B\u5168\u7247\u65F6\u95F4\u4E0E\u76EE\u6807\u8BEF\u5DEE\u4E0D\u8D85\u8FC7 10%\u3002\n\n---\n\n## C. \u53E3\u64AD\u53F0\u8BCD\u7A3F\uFF08Node 4\uFF09\n\n### \u56FA\u5B9A\u7ED3\u6784\n\n1. \u9876\u90E8\u6458\u8981\uFF1A\u76EE\u6807\u65F6\u957F\u3001\u8BED\u6C14\u3001\u5F55\u5236\u65B9\u5F0F\u3001\u753B\u9762\u6807\u8BB0\u7EA6\u5B9A\u3001\u4E8B\u5B9E\u8FB9\u754C\u3002\n2. \u6309\u6210\u7247\u65F6\u95F4\u6BB5\u7684\u5B8C\u6574\u9010\u5B57\u53F0\u8BCD\uFF1B\u6BCF\u4E2A\u8BED\u4E49\u5355\u5143\u5FC5\u987B\u9644\uFF1A\n\n`\u53F0\u8BCD ID\uFF5C\u6210\u7247\u65F6\u95F4\uFF5C\u53F0\u8BCD\uFF5C\u4FE1\u606F\u4EFB\u52A1\uFF5C\u753B\u9762\u5F00\u59CB/\u5207\u6362/\u5C40\u90E8\u653E\u5927/\u9000\u51FA\uFF5C\u955C\u5934 ID\uFF5C\u8BC1\u636E/\u7D20\u6750 ID`\n\n3. CTA\uFF1A\u53EA\u4ECE\u5DF2\u8BC1\u660E\u4EF7\u503C\u63A8\u51FA\u4E0B\u4E00\u6B65\uFF0C\u4E0D\u5806\u53E3\u53F7\u3002\n4. \u5B9E\u62CD\u56FA\u5B9A\u8F93\u5165\u6587\u672C\uFF1A\u6309\u754C\u9762/\u5DE5\u5177\u5355\u5217\uFF0C\u4FDD\u8BC1\u4E0E\u5206\u955C\u548C\u5B9E\u9645\u5C4F\u5F55\u4E00\u81F4\u3002\n5. \u53F0\u8BCD\u81EA\u68C0\uFF1A\u4E8B\u5B9E\u3001\u753B\u9762\u8BC1\u660E\u3001\u8282\u594F\u3001\u4EE3\u8BCD\u3001\u672A\u8BC1\u5B9E\u5185\u5BB9\u3002\n\n### \u786C\u7EA6\u675F\n\n- \u5F00\u5934\u5148\u7ED3\u679C\u6216\u65AD\u70B9\uFF1B\u7B2C\u4E00\u4EBA\u79F0\u627F\u62C5\u5B9E\u6D4B/\u64CD\u4F5C\uFF0C\u7B2C\u4E8C\u4EBA\u79F0\u53EA\u7528\u4E8E\u4EF7\u503C\u8F6C\u8BD1\u6216 CTA\u3002\n- \u6BCF\u53E5\u8BDD\u53EA\u627F\u62C5\u4E00\u4E2A\u4FE1\u606F\u4EFB\u52A1\uFF1B\u6BCF 15\u201330 \u79D2\u81F3\u5C11\u6709\u65B0\u7ED3\u679C\u3001\u5224\u65AD\u6216\u63A8\u8FDB\u3002\n- \u753B\u9762\u51FA\u73B0\u65F6\u53EA\u80FD\u8BF4\u5B83\u5B9E\u9645\u80FD\u8BC1\u660E\u7684\u5185\u5BB9\uFF1B\u4E0D\u5F97\u865A\u6784\u6570\u636E\u3001\u53CD\u9988\u3001\u754C\u9762\u6216\u4F53\u9A8C\u3002\n- \u4E0D\u5C06\u529F\u80FD\u6E05\u5355\u6539\u6210\u53E3\u8BED\uFF0C\u4E0D\u7528\u8FDE\u7EED\u9632\u5FA1\u5F0F\u5BF9\u6BD4\u53E5\u3002\u53E3\u64AD\u7A3F\u4E0D\u6DF7\u5165\u673A\u4F4D\u3001\u91C7\u8D2D\u4E0E\u526A\u8F91\u4EFB\u52A1\u3002\n\n---\n\n## D. \u53E3\u64AD\u5F55\u5236\u6267\u884C\u7A3F\uFF08Node 4\uFF09\n\n### \u56FA\u5B9A\u7ED3\u6784\n\n1. \u5F55\u5236\u5B89\u6392\u603B\u89C8\uFF1A`\u4EFB\u52A1\u7C7B\u578B\uFF5C\u6709\u6548\u53F0\u8BCD\u91CF\uFF5C\u5EFA\u8BAE\u539F\u59CB\u5F55\u5236\u91CF\uFF5C\u73AF\u5883\uFF5C\u4EA4\u4ED8\u6587\u4EF6\u7EC4`\u3002\n2. \u771F\u4EBA\u7EDF\u4E00\u673A\u4F4D\u89C4\u5219\uFF1A\u666F\u522B\u3001\u673A\u4F4D\u9AD8\u5EA6\u3001\u6784\u56FE\u7559\u767D\u3001\u7126\u6BB5\u3001\u4EBA\u7269\u4F4D\u7F6E\u3001\u5149\u7EBF\u3001\u80CC\u666F\u3001\u8BD5\u62CD\u3001\u6536\u97F3\u4E0E\u53D8\u5316\u539F\u5219\u3002\n3. `CAM` \u6E05\u5355\uFF1A`\u4EFB\u52A1 ID\uFF5C\u5BF9\u5E94\u53F0\u8BCD ID\uFF5C\u6210\u7247\u4F4D\u7F6E\uFF5C\u666F\u522B/\u7559\u767D\uFF5C\u8BED\u6C14\uFF5C\u5B8C\u6574\u53F0\u8BCD\uFF5C\u6587\u4EF6\u540D\uFF5C\u73B0\u573A\u9A8C\u6536`\u3002\n4. `VO` \u6E05\u5355\uFF1A`\u4EFB\u52A1 ID\uFF5C\u5BF9\u5E94\u53F0\u8BCD ID\uFF5C\u6210\u7247\u4F4D\u7F6E\uFF5C\u8986\u76D6\u753B\u9762\uFF5C\u53F0\u8BCD\uFF5C\u8BED\u901F/\u505C\u987F\uFF5C\u6587\u4EF6\u540D\uFF5C\u58F0\u97F3\u9A8C\u6536`\u3002\n5. `MIXED` \u6BB5\u9700\u540C\u65F6\u8BF4\u660E\u53EF\u89C1\u771F\u4EBA\u90E8\u5206\u548C\u7EAF\u97F3\u8F68\u90E8\u5206\u3002\n6. \u5F55\u5236\u987A\u5E8F\u3001\u524D\u540E\u9759\u9ED8\u3001\u51FA\u9519\u91CD\u5F55\u3001\u547D\u540D\u3001\u540C\u6B65\u68C0\u67E5\u4E0E\u5F52\u6863\u89C4\u5219\u3002\n\n### \u786C\u7EA6\u675F\n\n\u9664\u975E\u53D9\u4E8B\u4EFB\u52A1\u53E6\u6709\u8981\u6C42\uFF0C\u771F\u4EBA\u7EDF\u4E00\u56FA\u5B9A\u6B63\u9762\u4E2D\u8FD1\u666F\uFF1B\u6BCF\u4E2A\u8BED\u4E49\u5355\u5143\u524D\u540E\u7559 1\u20132 \u79D2\u9759\u9ED8\uFF0C\u9519\u8BEF\u65F6\u91CD\u5F55\u6574\u53E5\u3002\u6240\u6709\u53F0\u8BCD\u5FC5\u987B\u80FD\u8FFD\u6EAF\u5230\u5206\u955C\u65F6\u95F4\u7EBF\uFF0C\u672A\u5F55\u5230\u7684\u753B\u9762\u4E8B\u5B9E\u4E0D\u5F97\u65B0\u589E\u5230\u65C1\u767D\u3002\u6267\u884C\u7A3F\u63CF\u8FF0\u53EF\u5F55\u4EFB\u52A1\uFF0C\u4E0D\u9884\u8BBE\u4EBA\u5458\u5206\u5DE5\u3002\n\n---\n\n## E. \u524D\u671F\u7D20\u6750\u6267\u884C\u5305\uFF08Node 5\uFF09\n\n### \u56FA\u5B9A\u7ED3\u6784\n\n1. \u7F16\u5236\u76EE\u7684\u3001\u8F93\u5165\u7248\u672C\u3001\u76EE\u6807\u65F6\u957F\u4E0E\u9501\u5B9A\u8FB9\u754C\uFF1A\u8BF4\u660E\u54EA\u4E9B CAM/VO/\u56FA\u5B9A\u8F93\u5165\u5DF2\u7531 Node 4 \u9501\u5B9A\uFF0C\u4E0D\u80FD\u5728\u672C\u6587\u4EF6\u91CD\u65B0\u5B9A\u4E49\u3002\n2. \u5DF2\u9501\u5B9A\u4E0E\u5DF2\u6709\u8D44\u4EA7\uFF1A`ID\uFF5C\u72B6\u6001\uFF5C\u80FD\u8986\u76D6\u7684\u65F6\u95F4\u7EBF/\u4F7F\u7528\u4F4D\uFF5C\u9650\u5236`\u3002\n3. \u7EDF\u4E00\u6F14\u793A\u73AF\u5883\u4E0E\u6D4B\u8BD5\u9879\u76EE\uFF1A\u9879\u76EE\u540D/\u8D26\u53F7\u6216\u7A7A\u95F4/\u521D\u59CB\u72B6\u6001/\u9884\u671F\u7ED3\u679C/\u4E3B\u9898\u5B57\u53F7/\u9690\u79C1\u6E05\u7406/\u53EF\u91CD\u590D\u6027\u9A8C\u6536\u3002\n4. \u524D\u671F\u7D20\u6750\u603B\u89C8\uFF1A`\u7D20\u6750\u7EC4 ID\uFF5C\u6BCD\u7D20\u6750\u7C7B\u578B\uFF5C\u7528\u9014\uFF5C\u8BC1\u636E\u89D2\u8272\uFF5C\u6279\u6B21\uFF5C\u590D\u7528\u8986\u76D6\uFF5C\u4F18\u5148\u7EA7\uFF5C\u771F\u5B9E\u8BC1\u660E\u5C5E\u6027`\u3002\n5. \u5BF9\u6BCF\u4E2A\u7D20\u6750\u7EC4\uFF0C\u5B8C\u6574\u5199\u660E\uFF1A\n\n`\u8FDE\u7EED\u91C7\u96C6\u8DEF\u5F84\uFF5C\u56FA\u5B9A\u8F93\u5165\u6216\u64CD\u4F5C\u987A\u5E8F\uFF5C\u5FC5\u987B\u622A\u53D6\u7684\u6709\u6548\u7247\u6BB5\uFF5C\u6BCF\u7247\u6BB5\u53EF\u590D\u7528\u4F4D\u7F6E\uFF5C\u539F\u59CB\u65F6\u957F\u4E0E\u526A\u8F91\u4F59\u91CF\uFF5C\u5FC5\u987B\u53EF\u89C1\u72B6\u6001\uFF5C\u5F55\u5236\u8981\u6C42\uFF5C\u4E3B\u7248/\u5907\u4EFD\uFF5C\u6587\u4EF6\u547D\u540D\uFF5C\u9A8C\u6536\uFF5C\u4E8B\u5B9E\u6027\u964D\u7EA7\u8FB9\u754C`\n\n6. B-roll/\u75DB\u70B9\u8499\u592A\u5947\uFF1A\u6309\u6BCD\u7D20\u6750\u7EC4\u7EC4\u7EC7\uFF0C\u660E\u786E\u5176\u53EA\u627F\u62C5\u7684\u8868\u8FBE\u804C\u8D23\u3002\n7. \u540E\u671F\u56FE\u5F62\u4E0E\u975E\u4EBA\u58F0\u97F3\u9891\uFF1A\u7528\u9014\u3001\u6700\u5C11\u83B7\u53D6\u65B9\u5F0F\u3001\u7248\u6743/\u771F\u5B9E\u6027\u8FB9\u754C\u4E0E\u5EF6\u540E\u5236\u4F5C\u6761\u4EF6\u3002\n8. \u65F6\u95F4\u7EBF\u6620\u5C04\uFF1A`\u6210\u7247\u65F6\u95F4\u6BB5\uFF5C\u5DF2\u9501\u5B9A\u7D20\u6750\uFF5C\u672C\u5305\u8D1F\u8D23\u7D20\u6750\uFF5C\u7F3A\u5931\u540E\u679C`\u3002\n9. \u6700\u4F4E\u6210\u672C\u91C7\u96C6\u987A\u5E8F\uFF1A\u5148\u6F14\u793A\u73AF\u5883\u4E0E\u771F\u5B9E\u8BC1\u660E\u94FE\uFF0C\u518D\u9AD8\u590D\u7528\u8F85\u52A9\u7D20\u6750\uFF0C\u6700\u540E\u6309\u7C97\u526A\u9700\u8981\u505A\u56FE\u5F62\u548C\u58F0\u97F3\u3002\n10. \u6700\u7EC8\u6587\u4EF6\u6811\u4E0E\u5F00\u62CD\u524D\u68C0\u67E5\u8868\u3002\n\n### \u786C\u7EA6\u675F\n\n\u771F\u5B9E\u4EA7\u54C1\u754C\u9762\u3001\u771F\u5B9E\u64CD\u4F5C\u4E0E\u771F\u5B9E\u7ED3\u679C\u5FC5\u987B\u4F5C\u4E3A\u72EC\u7ACB\u6838\u5FC3\u8BC1\u660E\u7D20\u6750\uFF0C\u4E0D\u80FD\u7531 AI \u751F\u6210 UI \u66FF\u4EE3\u3002\u5173\u952E\u6F14\u793A\u4FDD\u7559\u4E3B\u7248\u4E0E\u5907\u4EFD\uFF1B\u5173\u952E\u52A8\u4F5C\u524D\u540E\u4FDD\u7559\u53EF\u88C1\u5207\u4F59\u91CF\u3002B-roll \u4E0D\u6309\u955C\u5934\u9010\u6761\u62CD\uFF0C\u4E0D\u627F\u62C5\u4E8B\u5B9E\u8BC1\u660E\u3002\u4EFB\u4F55\u8BC1\u660E\u6027\u7D20\u6750\u65E0\u6CD5\u6EE1\u8DB3\u53EF\u89C1\u72B6\u6001\u65F6\uFF0C\u56DE\u6D41 Node 4 \u4FEE\u6539\u4E3B\u5F20\uFF1B\u4EC5\u89E3\u91CA\u6027\u5185\u5BB9\u624D\u53EF\u964D\u7EA7\u4E3A\u9759\u5E27\u3001\u56FE\u5F62\u3001B-roll \u6216\u97F3\u6548\u3002\n\n---\n\n## \u8DE8\u6587\u4EF6\u8FFD\u8E2A\u4E0E\u63D0\u4EA4\u524D\u9A8C\u6536\n\n\u63D0\u4EA4\u524D\u5FC5\u987B\u80FD\u5B8C\u6210\u4E0B\u9762\u8FD9\u6761\u8FFD\u8E2A\uFF0C\u4EFB\u4E00\u65AD\u70B9\u90FD\u4E0D\u80FD\u9501\u5B9A\uFF1A\n\n`\u6BB5\u843D ID \u2192 \u955C\u5934 ID \u2192 \u53F0\u8BCD ID \u2192 CAM/VO/MIXED \u4EFB\u52A1 ID \u2192 \u6E90\u7D20\u6750\u7EC4 ID \u2192 \u53EF\u62C6\u7247\u6BB5 ID \u2192 \u4F7F\u7528\u4F4D \u2192 \u9A8C\u6536\u9879`\n\n\u9010\u9879\u68C0\u67E5\uFF1A\n\n- \u6BCF\u6761\u6838\u5FC3\u4E3B\u5F20\u90FD\u6709\u771F\u5B9E\u8BC1\u636E\u3001\u65F6\u95F4\u4F4D\u7F6E\u548C\u9A8C\u6536\u72B6\u6001\u3002\n- \u6BCF\u4E2A\u53F0\u8BCD\u5355\u5143\u80FD\u88AB\u540C\u671F\u753B\u9762\u8BC1\u660E\u3002\n- \u6BCF\u4E2A\u6E90\u7D20\u6750\u6709\u8FDE\u7EED\u8DEF\u5F84\u3001\u53EF\u89C1\u72B6\u6001\u3001\u4F59\u91CF\u3001\u5907\u4EFD\u4E0E\u9690\u79C1/\u7248\u6743\u9650\u5236\u3002\n- \u6BCF\u4E2A\u9AD8\u590D\u7528\u7D20\u6750\u7684\u7247\u6BB5\u548C\u4F7F\u7528\u4F4D\u663E\u5F0F\u76F8\u8FDE\uFF1B\u4E00\u6B21\u6027\u7D20\u6750\u6709\u5FC5\u8981\u6027\u7406\u7531\u3002\n- \u6587\u4EF6\u4E4B\u95F4\u4E0D\u6539\u53D8\u4EA7\u54C1\u4E8B\u5B9E\u3001\u56FA\u5B9A\u8F93\u5165\u3001\u9879\u76EE\u6761\u4EF6\u3001\u65F6\u957F\u548C CTA\u3002\n- \u8F93\u51FA\u4E0D\u5F97\u7528\u201C\u89C1\u4E3B\u7A3F\u201D\u201C\u6309\u9700\u8865\u5145\u201D\u201C\u7C7B\u4F3C\u5904\u7406\u201D\u8DF3\u8FC7\u672C\u5951\u7EA6\u8981\u6C42\u7684\u680F\u76EE\u3002\n";
